alter table public.boards enable row level security;
alter table public.board_members enable row level security;
alter table public.cards enable row level security;

create or replace function public.is_board_member(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.board_members m
    where m.board_id = p_board_id
      and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_board_editor(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.board_members m
    where m.board_id = p_board_id
      and m.user_id = auth.uid()
      and m.role = 'editor'
  );
$$;

create or replace function public.board_is_archived(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.boards b
    where b.id = p_board_id
      and b.is_archived
  );
$$;

create or replace function public.can_write_to_board(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.board_members m
    where m.board_id = p_board_id
      and m.user_id = auth.uid()
      and m.role = 'editor'
      and not public.board_is_archived(p_board_id)
  );
$$;

revoke all on function public.is_board_member(bigint) from public, anon;
revoke all on function public.is_board_editor(bigint) from public, anon;
revoke all on function public.board_is_archived(bigint) from public, anon;
revoke all on function public.can_write_to_board(bigint) from public, anon;

grant execute on function public.is_board_member(bigint) to authenticated, service_role;
grant execute on function public.is_board_editor(bigint) to authenticated, service_role;
grant execute on function public.board_is_archived(bigint) to authenticated, service_role;
grant execute on function public.can_write_to_board(bigint) to authenticated, service_role;

