alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create or replace function public.is_friend_with(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.friendships f
    where (f.requester_id = p_user_id or f.addressee_id = p_user_id)
      and f.status = 'accepted'
  );
$$;

revoke all on function public.is_friend_with(uuid) from public;
grant execute on function public.is_friend_with(uuid) to authenticated;

create policy "friendships_select_participant"
on public.friendships
for select
to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy "friendships_insert_requester"
on public.friendships
for insert
to authenticated
with check (requester_id = auth.uid() and status = 'pending');

create policy "friendships_update_addressee_accept"
on public.friendships
for update
to authenticated
using (status = 'pending' and addressee_id = auth.uid())
with check (status = 'accepted' and addressee_id = auth.uid());

create policy "friendships_delete_participant"
on public.friendships
for delete
to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy "posts_select_public_or_friends_or_own"
on public.posts
for select
to authenticated
using (
  audience = 'public'
  or (audience = 'friends' and public.is_friend_with(author_id))
  or author_id = auth.uid()
);

create policy "posts_insert_own"
on public.posts
for insert
to authenticated
with check (author_id = auth.uid());

create policy "posts_update_own"
on public.posts
for update
to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

create policy "posts_delete_own"
on public.posts
for delete
to authenticated
using (author_id = auth.uid());

revoke all on table public.friendships from anon;
revoke all on table public.posts from anon;

grant select on table public.friendships to authenticated;
grant select, insert, update, delete on table public.friendships to authenticated;

grant select, insert, update, delete on table public.posts to authenticated;
grant usage, select on sequence public.posts_id_seq to authenticated;

grant all on table public.friendships to service_role;
grant all on table public.posts to service_role;
grant usage, select on sequence public.posts_id_seq to service_role;
