create or replace function public.enforce_item_votes_guard()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if coalesce(auth.role(), '') = 'service_role'
     or current_user in ('service_role', 'postgres', 'supabase_admin') then
    return new;
  end if;

  if new.user_id is distinct from auth.uid() then
    raise exception 'item_votes.user_id must match auth.uid()'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.roadmap_items r
    where r.id = new.item_id
