    v_increment := v_auction.min_increment;
    v_highest := v_auction.highest_bid;
    if p_amount < v_highest + v_increment then
      raise exception 'Bid must be at least % more than the current highest bid', v_increment;
    end if;
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_uid, p_amount);

  update public.auctions
     set highest_bid = p_amount,
         highest_bidder = v_uid
   where id = p_auction_id;

  return p_amount;
end;
$$;

