```sql
alter table public.classes enable row level security;
alter table public.class_spots enable row level security;

-- R5: anonymous visitors get nothing
revoke all on public.classes from anon;
revoke all on public.class_spots from anon;
revoke all on public.classes from authenticated;
revoke all on public.class_spots from authenticated;

-- R5: no app-side writes to classes (R1/R3/R4 only)
grant select on public.classes to authenticated;

-- R1: signed-in users see every class
create policy "Classes are readable by signed-in users"
  on public.classes
  for select
  to authenticated
  using (true);

-- R1: members see their own spots
create policy "Members see their own class spots"
  on public.class_spots
  for select
  to authenticated
  using (user_id = auth.uid());

-- R1: instructors see all spots in the classes they teach
create policy "Instructors see all spots in their classes"
  on public.class_spots
  for select
  to authenticated
  using (
    exists (
      select 1
      from public.classes c
      where c.id = class_spots.class_id
        and c.instructor_id = auth.uid()
    )
  );

-- R2 / R3: join as themselves, enrolled only while capacity allows
create policy "Members can join a class as themselves"
  on public.class_spots
  for insert
  to authenticated
  with check (
    user_id = auth.uid()
    and status in ('enrolled', 'waitlisted')
    and (
      status <> 'enrolled'
      or (
        select count(*)
        from public.class_spots s
        where s.class_id = class_spots.class_id
          and s.status = 'enrolled'
      ) < (
        select c.capacity
        from public.classes c
        where c.id = class_spots.class_id
      )
    )
  );

-- R3: move own waitlisted spot to enrolled only when there is room
create policy "Members can move own waitlisted spot to enrolled when room"
  on public.class_spots
  for update
  to authenticated
  using (
    user_id = auth.uid()
    and status = 'waitlisted'
  )
  with check (
    user_id = auth.uid()
    and status = 'enrolled'
    and exists (
      select 1
      from public.class_spots s
      where s.class_id = class_spots.class_id
        and s.status = 'enrolled'
      and s.user_id <> auth.uid()
    )
  );

-- R3 / R4: leave a class by deleting own spot, or instructor can remove any spot from their classes
create policy "Members can leave a class by deleting their own spot"
  on public.class_spots
  for delete
  to authenticated
  using (user_id = auth.uid());

create policy "Instructors can remove any spot from the classes they teach"
  on public.class_spots
  for delete
  to authenticated
  using (
    exists (
      select 1
      from public.classes c
      where c.id = class_spots.class_id
        and c.instructor_id = auth.uid()
    )
  );

-- R6: service role keeps full access (also bypasses RLS)
grant all on public.classes to service_role;
grant all on public.class_spots to service_role;
